import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;
import top.theillusivec4.curios.api.SlotTypeMessage;
import top.theillusivec4.curios.api.type.capability.ICuriosItemHandler;

@Mod(value="toolbelt")
public class ToolBelt {
    public static final String MODID = "toolbelt";
    private static final DeferredRegister<Item> ITEMS = DeferredRegister.create((IForgeRegistry)ForgeRegistries.ITEMS, (String)"toolbelt");
    private static final DeferredRegister<MenuType<?>> MENU_TYPES = DeferredRegister.create((IForgeRegistry)ForgeRegistries.MENU_TYPES, (String)"toolbelt");
    public static RegistryObject<ToolBeltItem> BELT = ITEMS.register("belt", () -> new ToolBeltItem(new Item.Properties().m_41487_(1)));
    public static RegistryObject<Item> POUCH = ITEMS.register("pouch", () -> new Item(new Item.Properties()));
    public static RegistryObject<RecipeSerializer<?>> SEWING_UGRADE_SERIALIZER = RegistryObject.createOptional((ResourceLocation)ToolBelt.location("sewing_upgrade"), (ResourceKey)Registries.f_256764_, (String)"toolbelt");
    public static RegistryObject<MenuType<BeltSlotContainer>> BELT_SLOT_MENU = MENU_TYPES.register("belt_slot_container", () -> new MenuType(BeltSlotContainer::new, FeatureFlags.f_244332_));
    public static RegistryObject<MenuType<BeltContainer>> BELT_MENU = MENU_TYPES.register("belt_container", () -> IForgeMenuType.create(BeltContainer::new));
    public static ToolBelt instance;
    public static final Logger logger;
    private static final String PROTOCOL_VERSION = "1.0";
    public static SimpleChannel channel;
    public static boolean controllableEnabled;
    private static final Capability<ICuriosItemHandler> CURIOS;

    public ToolBelt() {
        instance = this;
        ModLoadingContext modLoadingContext = ModLoadingContext.get();
        IEventBus modEventBus = FMLJavaModLoadingContext.get().getModEventBus();
        ITEMS.register(modEventBus);
        MENU_TYPES.register(modEventBus);
        modEventBus.addListener(this::construct);
        modEventBus.addListener(this::commonSetup);
        modEventBus.addListener(this::clientSetup);
        modEventBus.addListener(this::modConfig);
        modEventBus.addListener(this::imcEnqueue);
        modEventBus.addListener(this::gatherData);
        modEventBus.addListener(this::registerCapabilities);
        modEventBus.addListener(this::addItemsToTabs);
        MinecraftForge.EVENT_BUS.addListener(this::anvilChange);
        modLoadingContext.registerConfig(ModConfig.Type.SERVER, (IConfigSpec)ConfigData.SERVER_SPEC);
        modLoadingContext.registerConfig(ModConfig.Type.CLIENT, (IConfigSpec)ConfigData.CLIENT_SPEC);
        modLoadingContext.registerConfig(ModConfig.Type.COMMON, (IConfigSpec)ConfigData.COMMON_SPEC);
        if (ModList.get().isLoaded("sewingkit")) {
            SewingKitIntegration.init(modEventBus);
        }
        if (ModList.get().isLoaded("controllable")) {
            controllableEnabled = true;
            ControllableSupport.init();
        }
